Repair the complete CommonJS source below and return a corrected complete source file. It must export exactly `{ formatCivilDate }`. The function accepts a non-null, non-array object containing exactly integer properties `year`, `month`, and `day`. Extra or malformed properties throw `TypeError`. Years must be from 1 through 9999 and months from 1 through 12; violations throw `RangeError`. The day must exist in the given month under Gregorian leap-year rules, otherwise throw `RangeError`. Return `YYYY-MM-DD`, padding all components to fixed widths. Do not mutate the input.

```javascript
function isLeapYear(year) {
  return year % 4 === 0;
}

function formatCivilDate(parts) {
  if (parts === null || typeof parts !== 'object' || Array.isArray(parts)) throw new TypeError('Expected date parts');
  const keys = Object.keys(parts);
  if (keys.length !== 3 || !keys.includes('year') || !keys.includes('month') || !keys.includes('day') ||
      !Number.isInteger(parts.year) || !Number.isInteger(parts.month) || !Number.isInteger(parts.day)) {
    throw new TypeError('Invalid date shape');
  }
  const { year, month, day } = parts;
  if (year < 1 || year > 9999 || month < 1 || month > 12) throw new RangeError('Date part out of range');
  const limits = [31, isLeapYear(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (day < 1 || day > limits[month - 1]) throw new RangeError('Invalid day');
  return `${String(year).padStart(4, '0')}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

module.exports = { formatCivilDate };
```

