'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['formatCivilDate']);
const { formatCivilDate } = api;
assert.equal(typeof formatCivilDate, 'function');

const input = Object.freeze({ year: 2024, month: 2, day: 29 });
assert.equal(formatCivilDate(input), '2024-02-29');
assert.deepStrictEqual(input, { year: 2024, month: 2, day: 29 });
assert.equal(formatCivilDate({ year: 1, month: 1, day: 1 }), '0001-01-01');
assert.equal(formatCivilDate({ year: 9999, month: 12, day: 31 }), '9999-12-31');
assert.equal(formatCivilDate({ year: 2000, month: 2, day: 29 }), '2000-02-29');
assert.equal(formatCivilDate({ year: 2400, month: 2, day: 29 }), '2400-02-29');
assert.equal(formatCivilDate({ year: 2023, month: 4, day: 30 }), '2023-04-30');

for (const bad of [
  null, [], '2024-01-01', undefined, {},
  { year: 2024, month: 1 },
  { year: 2024, month: 1, day: 1, extra: true },
  { year: '2024', month: 1, day: 1 },
  { year: 2024, month: 1.5, day: 1 },
  { year: 2024, month: 1, day: NaN }
]) assert.throws(() => formatCivilDate(bad), TypeError);

for (const bad of [
  { year: 0, month: 1, day: 1 },
  { year: 10000, month: 1, day: 1 },
  { year: 2024, month: 0, day: 1 },
  { year: 2024, month: 13, day: 1 },
  { year: 2023, month: 2, day: 29 },
  { year: 1900, month: 2, day: 29 },
  { year: 2100, month: 2, day: 29 },
  { year: 2024, month: 2, day: 30 },
  { year: 2024, month: 4, day: 31 },
  { year: 2024, month: 1, day: 0 }
]) assert.throws(() => formatCivilDate(bad), RangeError);

